CREATE TABLE IF NOT EXISTS ride_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), passenger_id uuid NOT NULL REFERENCES users(id), biker_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'OPEN', fare_ngn bigint NOT NULL CHECK(fare_ngn>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS parcel_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES users(id), rider_id uuid REFERENCES users(id), receiver_phone text NOT NULL, receiver_otp_hash text, status text NOT NULL DEFAULT 'OPEN', fare_ngn bigint NOT NULL CHECK(fare_ngn>=0), created_at timestamptz NOT NULL DEFAULT now());
